package org.emp;

public class Employee {
	
		// TODO Auto-generated method stub
		public void empId() {
	        System.out.println("Employee ID : 101");
	    }

	    public void empName() {
	        System.out.println("Employee Name : John");
	    }

	    public void empDob() {
	        System.out.println("Employee DOB : 12/05/2000");
	    }

	    public void empPhone() {
	        System.out.println("Employee Phone : 9876543210");
	    }

	    public void empEmail() {
	        System.out.println("Employee Email : john@gmail.com");
	    }

	    public void empAddress() {
	        System.out.println("Employee Address : Chennai");
	    }

	    public static void main(String[] args) {
			// TODO Auto-generated method stub

	     
	        Employee emp = new Employee();

	        
	        emp.empId();
	        emp.empName();
	        emp.empDob();
	        emp.empPhone();
	        emp.empEmail();
	        emp.empAddress();
	    }
	
	

	}


